// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether * 1000000);
        vm.deal(address(c), amount);
        uint256 before = address(this).balance;
        c.withdrawAll();
        assertTrue(address(this).balance == before + amount && address(c).balance == 0);
    }
}
